//! Ada (GNAT): `azul.ads` / `azul.adb`, package `Azul` (generated by
//! `doc/src/codegen/v2/lang_ada`).
//!
//! Spellings: every C function is imported as `Az_<Type>_<Method>` with the
//! method in Pascal_Snake (`AzCssProperty_textColor` ->
//! `Az_CssProperty_Text_Color`, variant constructor `AzLayoutWidth_px` ->
//! `Az_LayoutWidth_Px`, reserved words get `_K`: `Az_OptionString_Some_K`);
//! a nullary function is called without parentheses. Types are `Az_<Type>`,
//! C-like enums Ada enumerations (qualified here: `Az_LayoutDisplay'(Flex)`),
//! a tagged union a variant record with discriminant `Tag` and one
//! `Payload_<Variant>` component per variant, so both structs and unions are
//! qualified aggregates (`Az_ColorU'(R => 255, ..)`,
//! `Az_LayoutWidthValue'(Tag => Exact, Payload_Exact => ..)`).
//!
//! Calls and aggregates nest; only a Vec needs a declared array
//! ([`super::linear`]): `T : aliased array (0 .. n-1) of Az_X;` filled
//! element by element, then `Az_XVec_Copy_From_Ptr (T (0)'Address, n)`.
//! Strings go through a local `To_Az_String` helper
//! (`Az_String_Copy_From_Bytes` over an aliased copy).
//!
//! Output: spec + body of package `Styles` in one file (split with
//! `gnatchop`); the project writes `styles.ads` / `styles.adb` separately.
//!
//! DOM export (package `Ui`): a builder chain updates one temporary
//! (`t1 := Az_Dom_With_Child (t1, ..);`); a parameter is an Ada `String`
//! with the component's default as its default expression, converted by
//! `To_Az_String (Title)` where it is used; a joined string is
//! `To_Az_String ("by " & Author)`. An app's layout callback is
//! `Ui.Layout`, a library-level function `with Convention => C` whose
//! `'Address` goes into the `Az_LayoutCallback` record.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use core::fmt::Write;

use super::linear::{item_blocker, linear_comments, lower_to_statements, LinearSyntax};
use crate::codegen::{
    ir::{snake_to_lower_camel, ComponentSpec, Expr, Ident, Item, LibrarySpec, Module, Prim},
    lang::{
        dom::{one_line, unused_params},
        module_any, variant_ctor_method, ConcatPart,
    },
    CodegenBackend, GeneratedFile,
};

/// The Ada printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Ada;

/// `is_ada_reserved` of `lang_ada/mod.rs` (Ada 2012 reserved words).
const RESERVED: &[&str] = &[
    "abort", "abs", "abstract", "accept", "access", "aliased", "all", "and", "array", "at",
    "begin", "body", "case", "constant", "declare", "delay", "delta", "digits", "do", "else",
    "elsif", "end", "entry", "exception", "exit", "for", "function", "generic", "goto", "if",
    "in", "interface", "is", "limited", "loop", "mod", "new", "not", "null", "of", "or",
    "others", "out", "overriding", "package", "pragma", "private", "procedure", "protected",
    "raise", "range", "record", "rem", "renames", "requeue", "return", "reverse", "select",
    "separate", "some", "subtype", "synchronized", "tagged", "task", "terminate", "then",
    "type", "until", "use", "when", "while", "with", "xor",
];

/// `is_ada_shadow` of `lang_ada/mod.rs`.
const SHADOWS: &[&str] = &[
    "system", "interfaces", "address", "string", "ada", "convention", "import", "export",
];

/// Names of package `Standard` that HIDE a use-visible enumeration literal
/// of the same name (a type is not overloadable), so such a literal must be
/// written as the expanded name `Azul.<Literal>` (e.g. `CssPropertyType`'s
/// `Float`).
const STANDARD_NAMES: &[&str] = &[
    "boolean", "character", "duration", "float", "integer", "long_float", "long_integer",
    "long_long_integer", "natural", "positive", "short_float", "short_integer",
    "wide_character", "wide_string", "wide_wide_character", "wide_wide_string",
];

/// `sanitize_identifier` of `lang_ada/mod.rs`.
fn sanitize(name: &str) -> String {
    let mut out = name.to_string();
    while out.starts_with('_') {
        out = format!("F{}", &out[1..]);
    }
    while out.ends_with('_') {
        out.pop();
        out.push('K');
    }
    let lower = out.to_ascii_lowercase();
    if RESERVED.contains(&lower.as_str()) || SHADOWS.contains(&lower.as_str()) {
        format!("{out}_K")
    } else {
        out
    }
}

/// `pascalize_method_name` of `lang_ada/functions.rs`: `_` at every
/// lowercase->uppercase boundary, then each `_`-separated word capitalized
/// and the rest lowered (`copyFromPtr` -> `Copy_From_Ptr`,
/// `matrix3D` -> `Matrix3d`).
fn pascalize_method(name: &str) -> String {
    let mut split = String::new();
    let mut chars = name.chars().peekable();
    while let Some(c) = chars.next() {
        split.push(c);
        if c.is_ascii_lowercase() && chars.peek().is_some_and(char::is_ascii_uppercase) {
            split.push('_');
        }
    }
    let mut out = String::new();
    let mut upper_next = true;
    for c in split.chars() {
        if c == '_' {
            out.push('_');
            upper_next = true;
        } else if upper_next {
            out.push(c.to_ascii_uppercase());
            upper_next = false;
        } else {
            out.push(c.to_ascii_lowercase());
        }
    }
    out
}

/// `pascalize_field_name` of `lang_ada/types.rs`.
fn pascalize_field(name: &str) -> String {
    let mut out = String::new();
    let mut upper_next = true;
    let mut prev_lower = false;
    for c in name.chars() {
        if c == '_' {
            out.push('_');
            upper_next = true;
            prev_lower = false;
            continue;
        }
        if prev_lower && c.is_ascii_uppercase() {
            out.push('_');
            upper_next = true;
        }
        if upper_next {
            out.push(c.to_ascii_uppercase());
            upper_next = false;
        } else {
            out.push(c.to_ascii_lowercase());
        }
        prev_lower = c.is_ascii_lowercase();
    }
    out
}

/// An enumeration literal / discriminant value.
fn literal(variant: &str) -> String {
    let lit = sanitize(variant);
    if STANDARD_NAMES.contains(&lit.to_ascii_lowercase().as_str()) {
        format!("Azul.{lit}")
    } else {
        lit
    }
}

/// `Az_<Class>_<Method>` for a C method name (`textColor`).
fn function(class: &str, c_method: &str) -> String {
    format!("Az_{class}_{}", sanitize(&pascalize_method(c_method)))
}

/// An Ada `String` expression holding the UTF-8 bytes of `s`: printable
/// ASCII in literals (`"` doubled), every other byte as `Character'Val (n)`
/// (an Ada literal cannot hold a line break).
fn ada_string(s: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut run = String::new();
    for b in s.bytes() {
        if (0x20..0x7f).contains(&b) {
            if b == b'"' {
                run.push_str("\"\"");
            } else {
                run.push(char::from(b));
            }
        } else {
            if !run.is_empty() || parts.is_empty() {
                parts.push(format!("\"{run}\""));
                run.clear();
            }
            parts.push(format!("Character'Val ({b})"));
        }
    }
    if !run.is_empty() || parts.is_empty() {
        parts.push(format!("\"{run}\""));
    }
    parts.join(" & ")
}

fn apply(f: &str, args: &[String]) -> String {
    if args.is_empty() {
        f.to_string()
    } else {
        format!("{f} ({})", args.join(", "))
    }
}

/// A style's Ada name: `style_btn` -> `Style_Btn`.
fn unit_name(item: &Item) -> String {
    sanitize(&pascalize_method(&item.name.snake()))
}

/// A parameter's Ada name: `text_2` -> `Text_2`.
fn ada_param(name: &Ident) -> String {
    sanitize(&pascalize_method(&name.snake()))
}

/// The package of a DOM export (`Ui`) or of styles (`Styles`).
fn package_name(m: &Module) -> &'static str {
    if m.is_dom() {
        "Ui"
    } else {
        "Styles"
    }
}

/// ` (Title : String := "Hello"; ..)`, or nothing for an item without
/// parameters.
fn params_decl(item: &Item) -> String {
    if item.params.is_empty() {
        return String::new();
    }
    let params: Vec<String> = item
        .params
        .iter()
        .map(|p| {
            let ty = if p.ty == "String" {
                "String".to_string()
            } else {
                format!("Az_{}", p.ty)
            };
            match &p.default {
                Some(Expr::Str(d)) if p.ty == "String" => {
                    format!("{} : {ty} := {}", ada_param(&p.name), ada_string(d))
                }
                _ => format!("{} : {ty}", ada_param(&p.name)),
            }
        })
        .collect();
    format!(" ({})", params.join("; "))
}

impl LinearSyntax for Ada {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        text.to_string()
    }

    fn boolean(&self, b: bool) -> String {
        // `bool` is `Interfaces.C.unsigned_char` in azul.ads
        String::from(if b { "1" } else { "0" })
    }

    fn clike(&self, ty: &str, variant: &str) -> String {
        format!("Az_{ty}'({})", literal(variant))
    }

    fn type_name(&self, ty: &str) -> String {
        format!("Az_{ty}")
    }

    fn array_type(&self, elem: &str, n: usize) -> String {
        format!("aliased array (0 .. {}) of Az_{elem}", n.saturating_sub(1))
    }

    fn call(&self, target: &str, class: &str, method: &str, args: &[String]) -> Vec<String> {
        let e = self.call_expr(class, method, args).unwrap_or_default();
        vec![format!("{target} := {e};")]
    }

    fn variant_call(&self, target: &str, ty: &str, variant: &str, args: &[String]) -> Vec<String> {
        let e = self.variant_expr(ty, variant, args).unwrap_or_default();
        vec![format!("{target} := {e};")]
    }

    fn union(
        &self,
        target: &str,
        ty: &str,
        variant: &str,
        tag: usize,
        payload: Option<&str>,
    ) -> Vec<String> {
        let e = self.union_expr(ty, variant, tag, payload).unwrap_or_default();
        vec![format!("{target} := {e};")]
    }

    fn set_field(&self, target: &str, _ty: &str, field: &str, value: &str) -> String {
        format!("{target}.{} := {value};", sanitize(&pascalize_field(field)))
    }

    fn set_elem(&self, arr: &str, index: usize, value: &str) -> String {
        format!("{arr} ({index}) := {value};")
    }

    fn vec_from_array(&self, target: &str, ty: &str, elem: &str, arr: &str, count: &str) -> Vec<String> {
        let e = self.vec_expr(ty, elem, arr, count).unwrap_or_default();
        vec![format!("{target} := {e};")]
    }

    fn vec_empty(&self, target: &str, ty: &str) -> Vec<String> {
        vec![format!("{target} := Az_{ty}_Create;")]
    }

    fn string(&self, target: &str, s: &str) -> Vec<String> {
        vec![format!("{target} := To_Az_String ({});", ada_string(s))]
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Float { text, .. } if text == "nan" || text.ends_with("inf") => {
                Some("Ada has no literal for NaN / infinity".to_string())
            }
            _ => None,
        }
    }

    fn call_expr(&self, class: &str, method: &str, args: &[String]) -> Option<String> {
        Some(apply(&function(class, &snake_to_lower_camel(method)), args))
    }

    fn variant_expr(&self, ty: &str, variant: &str, args: &[String]) -> Option<String> {
        Some(apply(&function(ty, &variant_ctor_method(variant)), args))
    }

    fn union_expr(
        &self,
        ty: &str,
        variant: &str,
        _tag: usize,
        payload: Option<&str>,
    ) -> Option<String> {
        let tag = literal(variant);
        Some(match payload {
            Some(p) => format!("Az_{ty}'(Tag => {tag}, Payload_{} => {p})", sanitize(variant)),
            None => format!("Az_{ty}'(Tag => {tag})"),
        })
    }

    fn struct_expr(&self, ty: &str, fields: &[(String, String)]) -> Option<String> {
        if fields.is_empty() {
            return Some(format!("Az_{ty}'(others => <>)"));
        }
        let fields: Vec<String> = fields
            .iter()
            .map(|(k, v)| format!("{} => {v}", sanitize(&pascalize_field(k))))
            .collect();
        Some(format!("Az_{ty}'({})", fields.join(", ")))
    }

    fn string_expr(&self, s: &str) -> Option<String> {
        Some(format!("To_Az_String ({})", ada_string(s)))
    }

    fn vec_expr(&self, ty: &str, _elem: &str, arr: &str, count: &str) -> Option<String> {
        Some(format!("Az_{ty}_Copy_From_Ptr ({arr} (0)'Address, {count})"))
    }

    fn vec_empty_expr(&self, ty: &str) -> Option<String> {
        Some(format!("Az_{ty}_Create"))
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        None
    }

    fn param_expr(&self, name: &Ident) -> Option<String> {
        Some(format!("To_Az_String ({})", ada_param(name)))
    }

    /// `To_Az_String ("by " & Author)`.
    fn concat_expr(&self, parts: &[ConcatPart<'_>]) -> Option<String> {
        let parts: Vec<String> = parts
            .iter()
            .map(|p| match p {
                ConcatPart::Lit(s) => ada_string(s),
                ConcatPart::Param(i) => ada_param(i),
            })
            .collect();
        Some(format!("To_Az_String ({})", parts.join(" & ")))
    }
}

/// The spec line and the body of one style function (`None` for the spec
/// line if the Ada bindings cannot build it: then only a comment).
fn item_fn(item: &Item) -> (Option<String>, String) {
    let name = unit_name(item);
    let decl = format!("function {name}{} return Az_{}", params_decl(item), item.ty);
    if let Some(reason) = item_blocker(&Ada, item) {
        return (
            None,
            format!("   --  {name}: not expressible with the Ada bindings: {reason}\n"),
        );
    }
    let st = lower_to_statements(&Ada, &item.value);
    let mut out = String::new();
    for line in linear_comments(item, &st) {
        out.push_str(&format!("   --  {line}\n"));
    }
    out.push_str(&format!("   {decl} is\n"));
    let unused: Vec<String> = unused_params(item).iter().map(|p| ada_param(&p.name)).collect();
    if !unused.is_empty() {
        out.push_str(&format!("      pragma Unreferenced ({});\n", unused.join(", ")));
    }
    for (n, t) in &st.decls {
        out.push_str(&format!("      {n} : {t};\n"));
    }
    out.push_str("   begin\n");
    for s in &st.body {
        out.push_str(&format!("      {s}\n"));
    }
    out.push_str(&format!("      return {};\n   end {name};\n", st.result));
    (Some(format!("   {decl};\n")), out)
}

const TO_AZ_STRING: &str = "   function To_Az_String (S : String) return Az_String is
      Buf : aliased constant String (1 .. S'Length) := S;
   begin
      return Az_String_Copy_From_Bytes (Buf'Address, 0, Interfaces.C.size_t (S'Length));
   end To_Az_String;
";

const HEADER: &str = "--  Generated by azul-css codegen (Ada). Do not edit by hand.\n";

/// (`styles.ads`, `styles.adb`) without the file header. A DOM export is
/// package `Ui`; an app's also declares `To_Az_String` (for the window
/// title) and the layout callback `Layout`.
fn spec_and_body(m: &Module) -> (String, String) {
    let package = package_name(m);
    let fns: Vec<(Option<String>, String)> = m.items.iter().map(item_fn).collect();
    let registration = m.library.as_ref().map(|lib| ada_registration(m, lib));
    let mut spec = String::new();
    if registration.is_some() {
        spec.push_str("with System;\n");
    }
    spec.push_str(&format!("with Azul; use Azul;\n\npackage {package} is\n\n"));
    for (decl, _) in &fns {
        if let Some(d) = decl {
            spec.push_str(d);
        }
    }
    if m.app.is_some() {
        spec.push_str(APP_SPEC);
    }
    if let Some((reg_spec, _)) = &registration {
        spec.push_str(reg_spec);
    }
    spec.push_str(&format!("\nend {package};\n"));
    let strings = m.app.is_some()
        || registration.is_some()
        || module_any(m, &|e| matches!(e, Expr::Str(_) | Expr::Param(_) | Expr::Concat(_)));
    let mut body = String::new();
    if strings {
        body.push_str("with Interfaces.C;\n\n");
    }
    body.push_str(&format!("package body {package} is\n"));
    if strings {
        body.push('\n');
        body.push_str(TO_AZ_STRING);
    }
    for (_, f) in &fns {
        body.push('\n');
        body.push_str(f);
    }
    if let Some(app) = &m.app {
        let root = sanitize(&pascalize_method(&app.root.snake()));
        let value = if app.is_body {
            root
        } else {
            format!("Az_Dom_With_Child (Az_Dom_Create_Body, {root})")
        };
        body.push_str(&format!(
            "\n   function Layout (Data : Az_RefAny; Info : Az_LayoutCallbackInfo) return Az_Dom \
             is\n      pragma Unreferenced (Data, Info);\n   begin\n      return {value};\n   end \
             Layout;\n"
        ));
    }
    if let Some((_, reg_body)) = &registration {
        body.push_str(reg_body);
    }
    body.push_str(&format!("\nend {package};\n"));
    (spec, body)
}

/// What the registration calls (only when a component takes parameters):
/// overlays read the model in place (`with Import, Address => ..`).
const REGISTRATION_HELPERS: &str = "
   --  The bytes of an AzString as an Ada String.
   function To_String (S : Az_String) return String is
      Chars : constant String (1 .. Natural (S.Vec.Len))
        with Import, Address => S.Vec.Ptr;
   begin
      return Chars;
   end To_String;

   --  The String value of the data-model field Name (the model at Model),
   --  or Fallback.
   function Model_String
     (Model : System.Address; Name : String; Fallback : String) return String
   is
      M : constant Az_ComponentDataModel with Import, Address => Model;
      Fields : constant array (1 .. Natural (M.Fields.Len)) of Az_ComponentDataField
        with Import, Address => M.Fields.Ptr;
   begin
      for F of Fields loop
         if To_String (F.Name) = Name
           and then F.Default_Value.Tag = Some_K
           and then F.Default_Value.Payload_Some_K.Tag = String_K
         then
            return To_String (F.Default_Value.Payload_Some_K.Payload_String_K);
         end if;
      end loop;
      return Fallback;
   end Model_String;

   --  A String field of a component's data model.
   function String_Field
     (Name : String; Value : String; Description : String) return Az_ComponentDataField is
   begin
      return (Name => To_Az_String (Name),
              Field_Type => Az_ComponentFieldType_String_K,
              Default_Value => Az_OptionComponentDefaultValue_Some_K
                (Az_ComponentDefaultValue_String_K (To_Az_String (Value))),
              Required => 0,
              Description => To_Az_String (Description));
   end String_Field;
";

/// The registration of a component library (`m.library`): (spec lines,
/// body text). Per component a default-arguments wrapper (in the spec: the
/// compile function names it), a C-convention render and compile function
/// (their `'Address` is the `ComponentDef`'s function pointer) and the
/// `ComponentDef`; then `Register_<Library>_Library` (C convention, the
/// function libazul calls) and `Add_<Library>_Library`, which registers it
/// on an app config. `azul.ads` imports `AzAppConfig_addComponentLibrary`
/// with the wrapper record where libazul takes the function pointer, so the
/// body imports it again as libazul exports it. Items the module does not
/// have are skipped.
fn ada_registration(m: &Module, lib: &LibrarySpec) -> (String, String) {
    let lp = sanitize(&pascalize_method(&Ident::from_text(&lib.name).snake()));
    let az = |s: &str| format!("To_Az_String ({})", ada_string(s));
    let components: Vec<(&ComponentSpec, &Item)> = lib
        .components
        .iter()
        .filter_map(|c| m.item(&c.item).map(|i| (c, i)))
        .collect();
    let mut spec = String::new();
    let mut s = String::from("\n   --  -- registration --\n");
    if components.iter().any(|(_, i)| !i.params.is_empty()) {
        s.push_str(REGISTRATION_HELPERS);
    }
    let mut defs: Vec<String> = Vec::new();
    for (c, item) in &components {
        let item_fn = unit_name(item);
        let cp = sanitize(&pascalize_method(&Ident::from_text(&c.name).snake()));
        let defaults: Vec<String> = item.params.iter().map(|p| ada_string(p.default_text())).collect();
        let call = if defaults.is_empty() {
            item_fn.clone()
        } else {
            format!("{item_fn} ({})", defaults.join(", "))
        };
        let _ = writeln!(spec, "   function {item_fn}_Default return Az_Dom;");
        let _ = write!(
            s,
            "\n   --  `{}:{}` with its default arguments.\n   function {item_fn}_Default return \
             Az_Dom is\n   begin\n      return {call};\n   end {item_fn}_Default;\n",
            one_line(&lib.name),
            one_line(&c.name)
        );
        let args: Vec<String> = item
            .params
            .iter()
            .map(|p| {
                format!(
                    "Model_String (Model, {}, {})",
                    ada_string(&p.name.snake()),
                    ada_string(p.default_text())
                )
            })
            .collect();
        let render_call = if args.is_empty() {
            item_fn.clone()
        } else {
            format!("{item_fn} ({})", args.join(", "))
        };
        let unreferenced = if item.params.is_empty() {
            "Def, Model, Map"
        } else {
            "Def, Map"
        };
        let _ = write!(
            s,
            "\n   function {cp}_Render_Fn\n     (Def : System.Address; Model : System.Address; Map : \
             System.Address)\n      return Az_ResultStyledDomRenderDomError\n     with Convention => \
             C;\n\n   function {cp}_Render_Fn\n     (Def : System.Address; Model : System.Address; Map \
             : System.Address)\n      return Az_ResultStyledDomRenderDomError\n   is\n      pragma \
             Unreferenced ({unreferenced});\n   begin\n      return \
             Az_ResultStyledDomRenderDomError_Ok\n        (Az_StyledDom_Create_From_Dom \
             ({render_call}));\n   end {cp}_Render_Fn;\n"
        );
        let _ = write!(
            s,
            "\n   function {cp}_Compile_Fn\n     (Def : System.Address; Target : System.Address; Model \
             : System.Address;\n      Indent : Interfaces.C.size_t) return \
             Az_ResultStringCompileError\n     with Convention => C;\n\n   function \
             {cp}_Compile_Fn\n     (Def : System.Address; Target : System.Address; Model : \
             System.Address;\n      Indent : Interfaces.C.size_t) return \
             Az_ResultStringCompileError\n   is\n      pragma Unreferenced (Def, Target, Model, \
             Indent);\n   begin\n      return Az_ResultStringCompileError_Ok ({});\n   end \
             {cp}_Compile_Fn;\n",
            az(&format!("{}.{item_fn}_Default", package_name(m)))
        );
        let _ = write!(s, "\n   function {cp}_Def return Az_ComponentDef is\n");
        let fields = if item.params.is_empty() {
            s.push_str("   begin\n");
            "Az_ComponentDataFieldVec_Create".to_string()
        } else {
            let n = item.params.len();
            let items: Vec<String> = item
                .params
                .iter()
                .enumerate()
                .map(|(i, p)| {
                    let desc = c.field_descriptions.get(i).map_or("", String::as_str);
                    format!(
                        "{i} => String_Field ({}, {}, {})",
                        ada_string(&p.name.snake()),
                        ada_string(p.default_text()),
                        ada_string(desc)
                    )
                })
                .collect();
            let _ = write!(
                s,
                "      Fields : aliased array (0 .. {}) of Az_ComponentDataField :=\n        ({});\n      \
                 Field_Vec : constant Az_ComponentDataFieldVec :=\n        \
                 Az_ComponentDataFieldVec_Copy_From_Ptr (Fields (0)'Address, {n});\n   begin\n      \
                 --  copyFromPtr cloned them.\n      for I in Fields'Range loop\n         \
                 Az_ComponentDataField_Delete (Fields (I)'Address);\n      end loop;\n",
                n - 1,
                items.join(",\n         ")
            );
            "Field_Vec".to_string()
        };
        let _ = write!(
            s,
            "      return (Id => Az_ComponentId_Create ({}, {}),\n              Display_Name => {},\n              \
             Description => {},\n              --  The CSS is applied per node by \
             {item_fn}.\n              Css => {},\n              Source => UserDefined,\n              \
             Data_Model => (Name => {}, Description => {}, Fields => {fields}),\n              \
             Render_Fn => {cp}_Render_Fn'Address,\n              Compile_Fn => \
             {cp}_Compile_Fn'Address,\n              Render_Fn_Source => Az_OptionString_None,\n              \
             Compile_Fn_Source => Az_OptionString_None);\n   end {cp}_Def;\n",
            az(&lib.name),
            az(&c.name),
            az(&c.display_name),
            az(&c.description),
            az(""),
            az(&c.data_model),
            az(&c.data_model_description),
        );
        defs.push(format!("{cp}_Def"));
    }
    let _ = write!(
        spec,
        "   --  The component library `{}` (the function libazul calls) and its\n   --  \
         registration on the app config at App_Config.\n   function Register_{lp}_Library \
         return Az_ComponentLibrary\n     with Convention => C;\n   procedure Add_{lp}_Library \
         (App_Config : System.Address);\n",
        one_line(&lib.name)
    );
    let _ = write!(s, "\n   function Register_{lp}_Library return Az_ComponentLibrary is\n");
    let components = if defs.is_empty() {
        s.push_str("   begin\n");
        "Az_ComponentDefVec_Create".to_string()
    } else {
        let items: Vec<String> = defs.iter().enumerate().map(|(i, d)| format!("{i} => {d}")).collect();
        let _ = write!(
            s,
            "      Defs : aliased array (0 .. {}) of Az_ComponentDef := ({});\n      Components : \
             constant Az_ComponentDefVec :=\n        Az_ComponentDefVec_Copy_From_Ptr (Defs \
             (0)'Address, {});\n   begin\n      --  copyFromPtr cloned them.\n      for I in \
             Defs'Range loop\n         Az_ComponentDef_Delete (Defs (I)'Address);\n      end \
             loop;\n",
            defs.len() - 1,
            items.join(", "),
            defs.len()
        );
        "Components".to_string()
    };
    let _ = write!(
        s,
        "      return (Name => {},\n              Version => {},\n              Description => \
         {},\n              Components => {components},\n              Exportable => 1,\n              \
         Modifiable => 0,\n              Data_Models => \
         Az_ComponentDataModelVec_Create,\n              Enum_Models => \
         Az_ComponentEnumModelVec_Create);\n   end Register_{lp}_Library;\n\n   procedure \
         Add_Component_Library_Fn\n     (App_Config : System.Address; Name : Az_String; \
         Register_Fn : System.Address)\n     with Import, Convention => C, External_Name => \
         \"AzAppConfig_addComponentLibrary\";\n\n   procedure Add_{lp}_Library (App_Config : \
         System.Address) is\n   begin\n      Add_Component_Library_Fn\n        (App_Config, {}, \
         Register_{lp}_Library'Address);\n   end Add_{lp}_Library;\n",
        az(&lib.name),
        az(&lib.version),
        az("Exported from AzBuilder"),
        az(&lib.name),
    );
    (spec, s)
}

/// What an app's package `Ui` exports besides its items: the string helper
/// (for the window title) and the layout callback, a library-level
/// C-convention function so its `'Address` is a plain C function pointer.
const APP_SPEC: &str = "   function To_Az_String (S : String) return Az_String;
   function Layout (Data : Az_RefAny; Info : Az_LayoutCallbackInfo) return Az_Dom
     with Convention => C;
";

/// The app's main procedure (`m.app`): register the binding's releaser (as
/// `examples/ada` does before `Azul_RefAny_Create`), then open the window
/// with `Ui.Layout` as the layout callback.
fn ada_app_main(m: &Module) -> String {
    let Some(app) = &m.app else {
        return String::new();
    };
    ADA_APP_MAIN
        .replace("{title_str}", &ada_string(&app.title))
        .replace("{title}", &one_line(&app.title))
}

/// [`ada_app_main`]'s text (`{title}`, `{title_str}` are replaced). azul.ads
/// imports `AzWindowCreateOptions_create` with the `Az_LayoutCallback`
/// record, but that C function takes the function pointer (the record form
/// is `..._createStruct`), so the program imports it as libazul exports it.
const ADA_APP_MAIN: &str = r#"--  {title} - generated by AzBuilder (azul-css codegen, Ada).
--  Copy target/codegen/azul.ads + azul.adb and libazul here, then:
--    gprbuild -P azul_app.gpr && ./obj/main
with System;
with Azul; use Azul;
with Ui;

procedure Main is
   type App_Data is record
      Unused : Integer;
   end record;
   Model : aliased App_Data := (Unused => 0);

   --  AzWindowCreateOptions_create as libazul exports it: it takes the
   --  layout function itself (azul.ads declares it with the wrapper record).
   function Window_Create_Options_Create (Layout_Callback : System.Address)
     return Az_WindowCreateOptions
     with Import, Convention => C, External_Name => "AzWindowCreateOptions_create";

   Window : Az_WindowCreateOptions := Window_Create_Options_Create (Ui.Layout'Address);
   App : aliased Az_App;
begin
   Azul_Host_Invoker_Init;
   Window.Window_State.Title := Ui.To_Az_String ({title_str});
   App := Az_App_Create (Azul_RefAny_Create (Model'Address), Az_AppConfig_Create);
   Az_App_Run (App'Address, Window);
end Main;
"#;

impl CodegenBackend for Ada {
    fn lang(&self) -> &'static str {
        "ada"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["gnat"]
    }

    fn display_name(&self) -> &'static str {
        "Ada"
    }

    fn extension(&self) -> &'static str {
        "adb"
    }

    fn exports_dom(&self) -> bool {
        true
    }

    fn emit_module(&self, m: &Module) -> String {
        let (spec, body) = spec_and_body(m);
        let file = package_name(m).to_ascii_lowercase();
        format!(
            "{HEADER}--  Two compilation units ({file}.ads + {file}.adb): split them with\n--  \
             `gnatchop {file}.adb`.\n{spec}\n{body}"
        )
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let (spec, body) = spec_and_body(m);
        if m.app.is_some() {
            return vec![
                GeneratedFile {
                    path: "azul_app.gpr".to_string(),
                    contents: gpr("Azul_App"),
                },
                GeneratedFile {
                    path: "ui.ads".to_string(),
                    contents: format!("{HEADER}{spec}"),
                },
                GeneratedFile {
                    path: "ui.adb".to_string(),
                    contents: format!("{HEADER}{body}"),
                },
                GeneratedFile {
                    path: "main.adb".to_string(),
                    contents: ada_app_main(m),
                },
            ];
        }
        let mut main = String::from(
            "--  Copy target/codegen/azul.ads + azul.adb and libazul here, then:\n--    \
             gprbuild -P azul_styles.gpr && ./obj/main\nwith Ada.Text_IO;\nwith \
             Interfaces.C;\nwith Azul; use Azul;\nwith Styles;\n\nprocedure Main is\n",
        );
        let built: Vec<&Item> = m
            .items
            .iter()
            .filter(|i| item_blocker(&Ada, i).is_none())
            .collect();
        for item in &built {
            let name = unit_name(item);
            main.push_str(&format!(
                "   {name}_Value : constant Az_{} := Styles.{name};\n",
                item.ty
            ));
        }
        main.push_str("begin\n");
        for item in &built {
            let name = unit_name(item);
            main.push_str(&format!(
                "   Ada.Text_IO.Put_Line\n     (\"{name}:\" & Interfaces.C.size_t'Image \
                 ({name}_Value.Len) & \" properties\");\n"
            ));
        }
        if built.is_empty() {
            main.push_str("   null;\n");
        }
        main.push_str("end Main;\n");
        vec![
            GeneratedFile {
                path: "azul_styles.gpr".to_string(),
                contents: gpr("Azul_Styles"),
            },
            GeneratedFile {
                path: "styles.ads".to_string(),
                contents: format!("{HEADER}{spec}"),
            },
            GeneratedFile {
                path: "styles.adb".to_string(),
                contents: format!("{HEADER}{body}"),
            },
            GeneratedFile {
                path: "main.adb".to_string(),
                contents: main,
            },
        ]
    }
}

/// The GNAT project file of a project named `name` whose main is `main.adb`.
fn gpr(name: &str) -> String {
    format!(
        "project {name} is\n\n   for Languages use (\"Ada\");\n   for Source_Dirs use \
         (\".\");\n   for Object_Dir use \"obj\";\n   for Exec_Dir use \"obj\";\n   for Main use \
         (\"main.adb\");\n\n   package Compiler is\n      for Default_Switches (\"Ada\") use \
         (\"-gnat2012\");\n   end Compiler;\n\n   package Linker is\n      for Default_Switches \
         (\"Ada\") use (\"-L.\", \"-lazul\");\n   end Linker;\n\nend {name};\n"
    )
}
